private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null) {
        return null;
    }

    TreeNode<T> newParent = node.left;
    node.left = newParent.right;
    newParent.right = node;
    node.setParent(newParent);
    if (newParent.left != null) {
        newParent.left.setParent(node);
    }

    return newParent;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null || node.left == null) {
        throw new IllegalArgumentException("Node to rotate must have a left child");
    }

    TreeNode<T> right = node.left;
    TreeNode<T> newParent = right;
    right.parent = node.parent;
    node.left = right.right;
    if (right.right != null) {
        right.right.parent = node;
    }
    newParent.right = node;
    node.parent = newParent;
    return newParent;
}

