    node.left = temp.right;
    temp.right = node;
    return temp;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) {
        throw new IllegalArgumentException("Node cannot be null");
    }

    TreeNode<T> newParent = node.left;
    node.left = newParent.right;
    newParent.right = node;

    node.height = Math.max(node.right.height, node.left.height) + 1;
    newParent.height = Math.max(newParent.right.height, newParent.left.height) + 1;

    return newParent;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.left == null) {
        // If the node or its left child is null, nothing to rotate
        return node;
    }

    TreeNode<T> newParent = node.left;
    node.left = newParent.right;
    newParent.right = node;

    return newParent;
}

