public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    // Check if the graph is null
    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }

    // Create a new graph instance with the same vertices and edges as the input graph
    Graph<V, E> newGraph = new Graph<>(graph);

    // Iterate over each vertex in the input graph
    for (V vertex : graph.vertices()) {
        newGraph.place(vertex, vertex);
    }

    // Create a new IsomorphicGraphMapping instance with the new graph
    return new IsomorphicGraphMapping<>(newGraph);
}

