public static <V,E>IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<>();
    Map<V, Node> nodeMapping = new LinkedHashMap<>();

    // Iterate through each node in the original graph
    for (Node node : graph.getNodeSet()) {
        // Create a new node in the destination graph that corresponds to the original node
        Node destinationNode = destinationGraph.addNode(node.getId());
        nodeMapping.put(node, destinationNode);
        mapping.addMapping(node.getId(), destinationNode.getId());
    }

    // Iterate through each edge in the original graph
    for (Edge edge : graph.getEdgeSet()) {
        V sourceVertex = edge.getSourceNode().getId();
        V targetVertex = edge.getTargetNode().getId();

        // Add an edge in the destination graph that corresponds to the original edge
        Node sourceNode = nodeMapping.get(sourceVertex);
        Node targetNode = nodeMapping.get(targetVertex);
        destinationGraph.addEdge(sourceNode.getId(), targetNode.getId(), edge.getId());
        mapping.addMapping(edge.getId(), edge.getId());
    }

    return mapping;
}

