    // Check if the file is null
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }

    // First, remove the file or directory
    if (!file.delete()) {
        throw new IOException("Failed to delete the file or directory: " + file.getAbsolutePath());
    }

    // If the file is a directory, recursively delete all subdirectories and files
    if (file.isDirectory()) {
        File[] files = file.listFiles();
        if (files != null) {
            for (File child : files) {
                forceDeleteOnExit(child);
            }
        }
    }
}

