private static byte[] toVarInt(int number) {
    byte[] varInt = new byte[9];
    int byteIndex = 0;
    while (number >= 0x80) {
        varInt[byteIndex++] = (byte)(0x80 | (number & 0x7F));
        number >>= 7;
    }
    varInt[byteIndex++] = (byte)number;
    return varInt;
}

