 * Split time ranges to insure the start time and end time is small then  {@link #FETCH_DATA_DURATION}
 */
protected List<TimeRange> buildTimeRanges(long start, long end) {
    if (start >= end)
        throw IllegalArgumentException("Start date must be before end date");

    List<TimeRange> timeRanges = new ArrayList<>();
    long maxStart = 0;
    long maxEnd = 0;

    while (start < end) {
        long duration = end - start;
        if (duration < FETCH_DATA_DURATION) {
            maxStart = start;
            maxEnd = end;
            timeRanges.add(new TimeRange(maxStart, maxEnd));
            break;
        } else {
            start += FETCH_DATA_DURATION;
            timeRanges.add(new TimeRange(maxStart, start));
            if (start > maxEnd)
                maxEnd = start;
        }
    }

    return timeRanges;
}

/**
 * Split time ranges to insure the start time and end time is small then  {@link #FETCH_DATA_DURATION}
 */
protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = end - start;
    if (duration <= FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(start, end));
    } else {
        // Calculate the maximum split point
        long maxSplitPoint = start + FETCH_DATA_DURATION / 2;
        // Recursively split the time range
        List<TimeRange> leftRanges = buildTimeRanges(start, maxSplitPoint);
        List<TimeRange> rightRanges = buildTimeRanges(maxSplitPoint, end);
        // Combine the results
        for (TimeRange range : leftRanges) {
            timeRanges.add(range);
        }
        for (TimeRange range : rightRanges) {
            timeRanges.add(range);
        }
    }
    return timeRanges;
}

public static List<TimeRange> buildTimeRanges(long start, long end) {
    if (start < 0 || end <= 0 || start > end) {
        throw new IllegalArgumentException("Invalid time range: start cannot be less than 0, end cannot be less than or equal to 0, and start must be less than or equal to end.");
    }

    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = FETCH_DATA_DURATION;

    while (start + duration <= end) {
        timeRanges.add(new TimeRange(start, Math.min(start + duration, end)));
        start += duration;
    }

    return timeRanges;
}

