/**
 * Split time ranges to insure the start time and end time is small then {@link #FETCH_DATA_DURATION}
 *
 * @param start The start timestamp of the time range
 * @param end   The end timestamp of the time range
 * @return A list of time ranges
 */
public static List<TimeRange> buildTimeRanges(long start, long end) {
    if (start >= end) {
        throw new IllegalArgumentException("Start timestamp should be less than end timestamp");
    }

    long duration = end - start;
    if (duration >= FETCH_DATA_DURATION) {
        // Split the time range if necessary
        long splitInterval = FETCH_DATA_DURATION / 2;
        long newStart = start;
        long newEnd = newStart + splitInterval;
        if (end > newEnd) {
            List<TimeRange> newRanges = buildTimeRanges(newStart, newEnd);
            newRanges.add(new TimeRange(newEnd, end));
            return newRanges;
        } else {
            return Collections.singletonList(new TimeRange(newStart, end));
        }
    } else {
        return Collections.singletonList(new TimeRange(start, end));
    }
}

