    if (timeBucket == 0 || dayStep == 0) {
        throw new IllegalArgumentException("Timebucket or dayStep cannot be zero.");
    }

    long startDay = timeBucket / dayStep * dayStep;
    long endDay = Math.min(startDay + dayStep, timeBucket);

    return (startDay + endDay) / 2;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket < 0 || dayStep <= 0) {
        throw new IllegalArgumentException("Time bucket cannot be negative and dayStep must be positive");
    }

    long timeBucketRange = 1L + timeBucketStep - 1;
    long timeBucketStart = timeBucket / timeBucketRange * timeBucketRange;
    long timeBucketEnd = timeBucketStart + timeBucketRange - 1;

    if (timeBucket >= timeBucketStart && timeBucket <= timeBucketEnd) {
