public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket <= 0 || dayStep <= 0) {
        throw new IllegalArgumentException("Time bucket and day step must be positive integers.");
    }

    long formattedTimeBucket = 0;
    while (timeBucket >= 1) {
        long weekDaySpecial = timeBucket % dayStep;
        if (weekDaySpecial == dayStep - 1) {
            formattedTimeBucket++;
            formattedTimeBucket = (formattedTimeBucket + dayStep - 1) / dayStep * dayStep;
        } else if (weekDaySpecial > dayStep - 1) {
            formattedTimeBucket++;
            formattedTimeBucket = (formattedTimeBucket + dayStep - weekDaySpecial) / dayStep * dayStep;
        } else {
            formattedTimeBucket += (formatTimeBucket + 1) / dayStep * dayStep;
        }
        timeBucket /= dayStep;
    }

    return formattedTimeBucket;
}

