    String decodedPath = u.getPath();

    // Remove leading '/'
    if (decodedPath.startsWith("/")) {
        decodedPath = decodedPath.substring(1);
    }

    // Decode encoded characters
    if (decode) {
        try {
            decodedPath = java.net.URLDecoder.decode(decodedPath, StandardCharsets.UTF_8.name());
