    double rightX = box.getMaxX();
    double centerX = box.getCenterX();

    double length = rightX - leftX;
    double leftLength = length / 2;
    double rightLength = length / 2;

    Point2D leftPoint = new Point2D.Double(leftX, box.getMinY());
    Point2D rightPoint = new Point2D.Double(rightX, box.getMinY());

    Box2D leftBox = new Box2D(leftPoint, leftLength, box.getHeight());
