    // Returns: 
    //     a Pair containing the two resulting boxes

    // Check if the box is null
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }

    // Calculate the midpoint of the x-axis
    double midX = box.getMinX() + (box.getMaxX() - box.getMinX()) / 2;

    // Create the two resulting boxes
    Box2D box1 = new Box2D(box.getMinX(), box.getMinY(), midX, box.getMaxY());
    Box2D box2 = new Box2D(midX, box.getMinY(), box.getMaxX(), box.getMaxY());

    // Return the tuple containing the two resulting boxes
    return new Tuple<>(box1, box2);
