public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = node.size();
    for (Object childNode : node.getChildren()) {
        if (childNode instanceof LinkedBuffer) {
            totalSize += writeTo(out, (LinkedBuffer) childNode);
        }
    }
    byte[] data = node.getData();
    out.write(data);
    return totalSize + data.length;
}

