public static Supplier<String> createStringSupplier(int start) {
    // Initialize an ArrayList to store unique strings
    ArrayList<String> uniqueStrings = new ArrayList<>();
    // Initialize an ArrayList to keep track of used indices
    ArrayList<Integer> usedIndices = new ArrayList<>();

    // Create a Supplier function
    Supplier<String> supplier = new Supplier<String>() {
        private int counter = start;
        @Override
        public String get() {
            // Continue generating strings until the uniqueStrings list exceeds the size of usedIndices
            if (uniqueStrings.size() < usedIndices.size()) {
                counter++;
            } else {
                // If a duplicate index is encountered, generate a new unique string
                counter = usedIndices.get(counter % usedIndices.size());
            }
            // Generate a unique string by converting the counter to a String
            String uniqueStr = String.valueOf(counter);
            // Add it to the uniqueStrings list and store its index in usedIndices
            uniqueStrings.add(uniqueStr);
            usedIndices.add(counter);
            return uniqueStr;
        }
    };
    return supplier;
}

