public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder();
    int i = 0;
    int length = str.length();

    while (i < length) {
        char ch = str.charAt(i);

        if (ch != '\\') {
            sb.append(ch);
            i++;
            continue;
        }

        i++;
        if (i == length) {
            throw new IllegalArgumentException("Unexpected end of string");
        }

        char nextChar = str.charAt(i);

        if (nextChar == 'n') {
            sb.append('\n');
        } else if (nextChar == 't') {
            sb.append('\t');
        } else if (nextChar == 'b') {
            sb.append('\b');
        } else if (nextChar == 'r') {
            sb.append('\r');
        } else if (nextChar == '\'') {
            sb.append('\'');
        } else if (nextChar == '"') {
            sb.append('\"');
        } else if (nextChar == '\\') {
            sb.append('\\');
        } else {
            throw new IllegalArgumentException("Unknown escape character");
        }
    }

    return sb.toString();
}

public static String unescapeJava(String str) {
    if (str == null) {
        return null;
    }

    StringBuilder result = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 < str.length()) {
                char nextChar = str.charAt(i + 1);
                switch (nextChar) {
                    case '\\':
                        result.append('\\');
                        break;
                    case 't':
                        result.append('\t');
                        break;
                    case 'n':
                        result.append('\n');
                        break;
                    case 'r':
                        result.append('\r');
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid escape sequence: \\");
                }
                i++; // Skip the next character that was parsed as an escape sequence
            } else {
                throw new IllegalArgumentException("Invalid escape sequence at the end of the string");
            }
        } else {
            result.append(c);
        }
    }

    return result.toString();
}

