            }
        }
    }

    return sb.toString();
}

private boolean jumpToNext(char ch) {
    if (ch == '\\' && isNextDelimiter(ch)) {
        return true;
    }
    return false;
}

private boolean isNextDelimiter(char ch) {
    return ch == '"' || ch == '\'' || ch == 'n' || ch == 't';
}

