private int computeBinaryLog(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }

    int maxShift = 0;
    while (n > 0) {
        n >>= 1;
        maxShift++;
    }

    return maxShift;
}

private int computeBinaryLog(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input cannot be negative");
    }

    if (n == 0) {
        return 0;
    }

    // Use logarithmic function for base 2 to find the highest power of 2 less than or equal to n
    int logValue = (int) Math.floor(Math.log(n) / Math.log(2));
    return logValue + 1;
}

