        return Action.CONTINUE;
    }
}

@Override public Action inspect(AtmosphereResource r){
    if (r == null) {
        throw new IllegalArgumentException("Resource cannot be null");
    }
    if (r.getTransport() == null) {
        throw new IllegalArgumentException("Transport cannot be null");
    }

    if (r.getTransport() == Transport.HTTP) {
        return Action.CONTINUE;
    } else if (r.getTransport() == Transport.GZIP) {
        return Action.CONTINUE;
    } else if (r.getTransport() == Transport.DETECTEDGZIP) {
        return Action.CONTINUE;
    } else {
        throw new UnsupportedOperationException("Unsupported transport: " + r.getTransport());
    }
}

public Action inspect(AtmosphereResource r) {   
    if (r == null) {
        throw new IllegalArgumentException("Input atmosphere resource cannot be null.");
    }

    TransportProtocol transport = r.getHeader("TRANSPORT");

    if (transport == null) {
        throw new IllegalArgumentException("Header 'TRANSPORT' not found in AtmosphereResource.");
    }

    if (transport.getCode() == TransportProtocol.HTTP) {
        r.suspend();
    }

    return Action.CONTINUE;
}

@Override
public Action inspect(AtmosphereResource r) {
    if (r == null) {
        return Action.CONTINUE;
    }

    if (r.getTransport() == null) {
        return Action.CONTINUE;
    }

    r.suspend();
    return Action.CONTINUE;
}

@Override public Action inspect(AtmosphereResource r) {
    if (r == null) {
        throw new IllegalArgumentException("Input atmosphere resource cannot be null");
    }

    switch (r.getTransport()) {
        case HTTP:
            r.accomplishAction(Action.SUSPEND);
            return Action.CONTINUE;
        case HTTPS:
            r.accomplishAction(Action.SUSPEND);
            return Action.CONTINUE;
        default:
            throw new IllegalArgumentException("Unsupported transport type");
    }
}

