public GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    GraphPath<V, E> graphPath = new GraphPath<>(graph);
    for (Edge<E> edge : tour) {
        graphPath.addNode(edge.getSourceVertex());
        graphPath.addNode(edge.getTargetVertex());
        graphPath.addEdge(edge.getSourceVertex(), edge.getTargetVertex());
    }
    return graphPath;
}

private GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    GraphPath<V,E> graphPath = new UnmarkedGraphPath<>();
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input cannot be null");
    }

    for (E edge : tour) {
        Vertex<V> src = graph.getVertex(edge.getSource());
        Vertex<V> dest = graph.getVertex(edge.getDestination());

        if (src == null || dest == null) {
            if (src == null && dest != null) {
                graphPath.addEdge(dest, null);
            } else if (dest == null && src != null) {
                graphPath.addEdge(null, src);
            } else {
                throw new IllegalArgumentException("Edge involves vertices not in the graph");
            }
        } else {
            if (src.isMarked() || dest.isMarked()) {
                throw new RuntimeException("A cycle is detected in the tour");
            }
            src.setMarked(true);
            dest.setMarked(true);
            graphPath.add edge(src, dest);
            src.setMarked(false);
            dest.setMarked(false);
        }
    }

    return graphPath;
}

/**
 * Transform from a Set representation to a graph path.
 * @param tour a set containing the edges of the tour
 * @param graph the graph
 * @return a graph path
 */
protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null || graph.getVertices().isEmpty()) {
        throw new IllegalArgumentException("Invalid input: tour or graph cannot be null or empty.");
    }

    Map<V, V> pathMap = new HashMap<>();
    Map<V, Integer> vertexIndexMap = new HashMap<>();

    int vertexIndex = 0;
    for (V vertex : graph.getVertices()) {
        vertexIndexMap.put(vertex, vertexIndex++);
    }

    for (E edge : tour) {
        V sourceVertex = edge.getSource();
        V targetVertex = edge.getTarget();

        if (!pathMap.containsKey(sourceVertex)) {
            pathMap.put(sourceVertex, targetVertex);
        } else {
            throw new IllegalStateException("Duplicate edge found: " + edge);
        }
    }

    GraphPath<V, E> path = new GraphPath<>();
    for (V vertex : graph.getVertices()) {
        path.add(vertex);
    }

    for (Map.Entry<V, V> entry : pathMap.entrySet()) {
        path.setEdge(entry.getKey(), entry.getValue());
    }

    return path;
}

/**
 * Transform from a Set representation to a graph path.
 * 
 * @param tour a set containing the edges of the tour
 * @param graph the graph
 * @return a graph path
 */
public GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null || tour.isEmpty() || graph.isEmpty()) {
        throw new IllegalArgumentException("Invalid parameter(s)");
    }

    GraphPath<V, E> path = new GraphPath<>();

    for (E edge : tour) {
        if (!graph.containsEdge(edge)) {
            throw new IllegalArgumentException("Edge " + edge + " not found in the graph");
        }
        path.addVertex(graph.getVertex(source(edge)));
        path.addVertex(graph.getVertex(target(edge)));
        path.addEdge(edge);
    }

    return path;
}

private V source(E edge) {
    return edge.source();
}

private V target(E edge) {
    return edge.target();
}

@Override
protected <V extends Vertex, E extends Edge<V>> GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null || graph.vertices().isEmpty()) {
        throw new IllegalArgumentException("Invalid input: tour or graph cannot be null or empty");
    }

    // Step 1: Check if each edge in tour is valid in the graph
    for (E edge : tour) {
        if (!graph.containsEdge(edge)) {
            throw new IllegalArgumentException("Edge " + edge + " is not valid in the graph");
        }
    }

    // Step 2: Construct the Tour path
    List<V> pathVertices = new ArrayList<>();
    for (E edge : tour) {
        pathVertices.add(edge.getSource());
    }
    pathVertices.add(tour.iterator().next().getTarget());
    return new FixedLengthPath<>(graph, pathVertices);
}

