/**
 * Computes a suffix sum of the {@code bounds}. Returns computed suffix sum and the sum of all elements in the
 * {@code bounds} list.
 * @param bounds list of integers.
 * @return computed pair of suffix sum list and a sum of all elements.
 */
public Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSum = new ArrayList<>();
    long sum = 0;

    for (int i = bounds.size() - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffixSum.add(sum);
    }

    // The sum can be obtained by summing the last half of the list
    long totalSum = LongStream.range(0, bounds.size() / 2).mapToLong(i -> bounds.get(i)).sum() * 2;

    return new Pair<>(suffixSum, totalSum);
}

public Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    int n = bounds.size();
    List<Integer> suffixSum = new ArrayList<>(n + 1);
    suffixSum.set(0, 0);
    for (int i = 1; i <= n; i++) {
        suffixSum.set(i, suffixSum.get(i - 1) + bounds.get(i - 1));
    }
    long sum = 0;
    for (int num : bounds) {
        sum += num;
    }
    return new Pair<>(suffixSum, sum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Bounds list cannot be null or empty");
    }

    List<Integer> suffixSumList = new ArrayList<>();
    long sum = 0;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        suffixSumList.add(sum);
        sum += bounds.get(i);
    }
    return new Pair<>(suffixSumList, sum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSum = new ArrayList<>(bounds);
    long totalSum = 0;

    // Calculate suffix sum from right to left
    for (int i = bounds.size() - 2; i >= 0; i--) {
        suffixSum.set(i, suffixSum.get(i + 1) + bounds.get(i));
    }

    // Calculate total sum of the bounds list
    for (Integer bound : bounds) {
        totalSum += bound;
    }

    // Return the computed pair of suffix sum list and total sum
    return Pair.of(suffixSum, totalSum);
}

public Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Bounds list cannot be null or empty");
    }

    List<Integer> suffixSumList = new ArrayList<>();
    Long prefixSum = 0L;
    Long totalSum = 0L;

    for (Integer bound : bounds) {
        prefixSum += bound;

        suffixSumList.add(prefixSum);
        totalSum += bound;
    }

    return new Pair<>(suffixSumList, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Array cannot be null or empty");
    }

    if (from < 0 || from >= arr.length || to < from || to >= arr.length) {
        throw new IndexOutOfBoundsException("Invalid range indices");
    }

    int left = from;
    int right = to;

    while (left < right) {
        V temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;

        left++;
        right--;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    while (from < to) {
        // Swap elements at the from and to indices
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        // Move towards the center of the array
        from++;
        to--;
    }
}

