        from++;
        to--;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    if (from < 0 || to >= arr.length) {
        throw new IllegalArgumentException("Indices out of range");
    }
    if (from >= to) {
        return; // No need to reverse if range is already in reverse order
    }

    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

