        decoded[i / 4] = (byte) (value & 0xFF);
    }

    // Remove padding
    while (decoded[len - 1] == 0) {
        len--;
    }

    // Convert byte array to string
    for (byte b : decoded) {
        result.append((char) b);
    }

    return result.toString();
}

