private List<Pair<List<Pair<Integer,Integer>>, E>> computeLocalSeparatorList(Graph graph, Edge edge) {
    Set<Edge> visitedEdges = new HashSet<>();
    List<Pair<List<Pair<Integer,Integer>>, E>> localSeparatorList = new ArrayList<>();
    Set<Item> unexploredItems = new HashSet<>();
    Set<Item> visitedItems = new HashSet<>();
    Set<Integer> yetUnexploredElementsInComponents = new HashSet<>(graph.componentSizes().keySet());

    Set<Entity> stack = new HashSet<>();
    stack.add(new Item(edge.source(), null));
    unexploredItems.add(new Item(edge.source(), null));

    while (!stack.isEmpty()) {
        Item current = stack.pop();
        if (visitedItems.contains(current)) continue;
        visitedItems.add(current);

        yetUnexploredElementsInComponents.remove(current.element);

        for (Edge neighborEdge : getNeighbors(graph, current.element)) {
            if (!(neighborEdge == edge)) {
                if (visitedEdges.contains(neighborEdge)) continue;
                if (unexploredItems.contains(new Item(neighborEdge.target(), neighborEdge))) {
                    stack.add(new Item(neighborEdge.target(), neighborEdge));
                    unexploredItems.remove(new Item(neighborEdge.target(), neighborEdge));
                }
            }
        }
    }

    for (Item item : unexploredItems) {
        Stack<RandomElement> localSeparator = new Stack<>();
        localSeparator.push(new RandomElement(item.element));

        while (localSeparator.peek().element != null) {
            Entity source = localSeparator.peek().element;
            if (!visitedItems.contains(source)) {
                visitedItems.add(source);
                localSeparator.push(new RandomElement(getNeighbors(graph, source).iterator().next().target()));
            } else {
                localSeparator.pop();
                if (!visitedItems.contains(source)) {
                    visitedItems.add(source);
                    localSeparator.push(new RandomElement(getNeighbors(graph, source).iterator().next().target()));
                }
            }

            if (yetUnexploredElementsInComponents.isEmpty()) break;
        }

        if (!localSeparator.isEmpty()) {
            List<RandomElement> localSeparatorList = new ArrayList<>();
            while (!localSeparator.isEmpty()) {
                localSeparatorList.add(localSeparator.pop());
            }
            localSeparatorList.reverse();
            localSeparatorList.forEach(randomElement -> {
                int source = randomElement.element;
                int target = localSeparatorList.get(0).element;
                localSeparatorList.set(0, source);
                localSeparatorList.set(1, target);
            });
            globalSeparatorList.add(new Pair<>(localSeparatorList, edge));
        }
    }

    return globalSeparatorList;
