    // Put the int value into the byte array
    newLength[newLength.length - 4] = (byte) ((intValue >> 24) & 0xFF);
    newLength[newLength.length - 3] = (byte) ((intValue >> 16) & 0xFF);
    newLength[newLength.length - 2] = (byte) ((intValue >> 8) & 0xFF);
    newLength[newLength.length - 1] = (byte) (intValue & 0xFF);

    // Update data with the new data
    data = newByteVector(newLength);
    return data;
}

