public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Check if the buffer is not null and not empty
    if (buf == null || buf.isEmpty()) {
        throw new IllegalArgumentException("Buffer must not be null or empty");
    }

    // Check if the start index is within the buffer's length
    if (nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("Start index out of bounds");
    }

    // Abbreviate the name by concatenating leading characters up to the specified index
    buf.append(buf.substring(0, nameStart));
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null || nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("Invalid buffer or start index");
    }

    int end = nameStart;
    while (end < buf.length() && Character.isWhitespace(buf.charAt(end))) {
        end++;
    }

    if (end == nameStart) {
        // If no characters are skipped, the full name is already appended
        buf.append(buf.substring(nameStart));
        return;
    }

    // Abbreviate the name
    while (end < buf.length() && !Character.isWhitespace(buf.charAt(end))) {
        buf.append(Character.toUpperCase(buf.charAt(end)));
        end++;
    }

    // If the last character is a space, remove it (e.g., "John Doe  -> John Doe")
    if (end > nameStart && buf.charAt(end - 1) == ' ') {
        buf.setLength(end - 1);
    }
}

