public void abbreviate(final int nameStart, final StringBuffer buf) {
    // ensures the provided name start index is within manageable bounds
    if (nameStart < 1 || nameStart > buf.length()) {
        throw new IllegalArgumentException("Name start is out of bounds.");
    }

    int lastSpaceIndex = -1; // to store the index of the last space from the start

    // traverse the buffer in reverse to identify the last space before the given start index
    for (int i = nameStart - 1; i >= 0; i--) {
        if (buf.charAt(i) == ' ') {
            lastSpaceIndex = i;
            break;
        }
    }

    // if a space is found, append three will words before it
    if (lastSpaceIndex != -1) {
        buf.append(lastSpaceIndex - nameStart + 3);
        buf.append("...");
    } else {
        // if no space is found, append as much as possible of the name up to the given start index
        buf.append(buf.substring(nameStart));
    }
}

