private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
        if (vertices.isEmpty() || vertices.size() == 1 || !graph.hasEdges(vertices)) {
            return true; // A set containing 0, 1, or no edges cannot be a clique.
        }

        V firstVertex = vertices.iterator().next();
        for (V vertex : vertices) {
            if (!graph.isNeighbor(firstVertex, vertex)) {
                return false; // Finding any edge other than between the first vertex and the others indicates the graph is not a clique.
            }
        }

        // At this point, all vertices are directly connected to the first vertex, so it must be the entire set to be a clique.
        return true;
    }

private static <V,E>boolean isClique(Graph<V,E> graph,Set<V> vertices){
    if(graph == null || vertices == null || vertices.size() == 0){
        throw new IllegalArgumentException("Graph or vertices set cannot be null or empty");
    }
    if(graph.vertexSet().size() != vertices.size()){
        throw new IllegalArgumentException("Number of vertices in graph must match number of vertices to induce");
    }

    for(V v : vertices){
        Set<V> neighbors = graph.neighbors(v);
        if(neighbors.size() != vertices.size() - 1){
            return false;
        }
        for(V w : vertices){
            if(neighbors.contains(w) && w != v){
                return false;
            }
        }
    }
    return true;
}

