private static <V,E>boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null || graph.size() == 0 || vertices.size() == 0 || vertices.size() > graph.size()) {
        throw new IllegalArgumentException("Invalid input: graph and vertices must not be null and vertices size must be less than or equal to graph size");
    }

    List<V> allVertices = new ArrayList<>(graph.vertexSet()); // Make a copy to avoid modifying the original graph
    List<V> subGraphVertices = new ArrayList<>(vertices);

    // Ensure subGraphVertices are a subset of allVertices
    if (!allVertices.containsAll(subGraphVertices)) {
        throw new IllegalArgumentException("Invalid input: subGraphVertices must be a subset of allVertices");
    }

    // If the subgraph has less than 2 vertices, it is trivially a clique
    if (subGraphVertices.size() < 2) {
        return true;
    }

    // Check for adjacency among all pairs of vertices in the subgraph
    for (int i = 0; i < subGraphVertices.size() - 1; i++) {
        V v1 = subGraphVertices.get(i);
        for (int j = i + 1; j < subGraphVertices.size(); j++) {
            V v2 = subGraphVertices.get(j);
            if (!graph.containsEdge(v1, v2)) {
                return false; // Found an edge that violates the clique property
            }
        }
    }

    return true;
}

/**
 * Check whether the subgraph of <code>graph</code> induced by the given <code>vertices</code> is complete, i.e. a clique.
 * @param graph the graph.
 * @param vertices the vertices to induce the subgraph from.
 * @return true if the induced subgraph is a clique.
 */
private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Precondition check: Vertices must be a subset of the graph's vertices
    if (vertices == null || vertices.isEmpty() || !vertices.containsAll(graph.vertices())) {
        throw new IllegalArgumentException("Vertices must be a subset of the graph's vertices");
    }

    if (vertices.size() <= 1) {
        return true; // A set with 0 or 1 vertex is always a clique
    }

    // Check for the presence of an edge between every pair of vertices in the subset
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!graph.hasEdge(v1, v2)) {
                return false; // A complete subgraph requires an edge between every pair of vertices
            }
        }
    }

    return true; // All checks passed, the subgraph is a clique
}

