public static String encodeTemplateNames(String s) throws Exception {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }

    StringBuilder encodedString = new StringBuilder();
    int i = 0;
    while (i < s.length()) {
        char c = s.charAt(i);
        if (c == '{' || c == '}') {
            // Percent-encode the '{' and '}' characters
            encodedString.append("%" + String.format("%02d", c));
        } else {
            encodedString.append(c);
        }
        i++;
    }

    return encodedString.toString();
}

public static String encodeTemplateNames(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }

    StringBuilder encodedString = new StringBuilder();
    Pattern pattern = Pattern.compile("[{\\}]", Pattern.CASE_INSENSITIVE);
    Matcher matcher = pattern.matcher(s);

    while (matcher.find()) {
        char c = matcher.group().charAt(0);
        encodedString.append('%').append(hexValue(c));
    }

    return encodedString.toString();
}

private static String hexValue(char c) {
    if (c >= '0' && c <= '9') {
        return String.valueOf(c);
    } else if (c >= 'A' && c <= 'Z') {
        return String.valueOf((char) (c - 'A' + 0xA));
    } else if (c >= 'a' && c <= 'z') {
        return String.valueOf((char) (c - 'a' + 0xA));
    } else {
        throw new IllegalArgumentException("Invalid character: " + c);
    }
}

